    <title>Codex Settings</title>
    <style>
        :root {
            --bg-color: #ffffff;
            --sidebar-bg: #f9fafb;
            --border-color: #e5e7eb;
            --text-primary: #111827;
            --text-secondary: #6b7280;
            --accent-color: #000000; /* Assuming dark mode accent or just black text */
            --hover-bg: #f3f4f6;
            --active-bg: #e5e7eb;
            --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-family);
            background-color: var(--bg-color);
            color: var(--text-primary);
            height: 100vh;
            display: flex;
            flex-direction: column;
            overflow: hidden; /* App-like feel */
        }

        /* --- Window Chrome (Simulated) --- */
        .window-chrome {
            height: 36px;
            background-color: #f3f4f6;
            border-bottom: 1px solid var(--border-color);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 10px;
            -webkit-app-region: drag;
            user-select: none;
            font-size: 13px;
        }

        .chrome-left, .chrome-center, .chrome-right {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .chrome-icon {
            width: 16px;
            height: 16px;
            fill: #374151;
            cursor: pointer;
        }

        .window-controls {
            display: flex;
            gap: 8px;
        }

        .control-btn {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            border: 1px solid #d1d5db;
        }
        .btn-min { background: transparent; }
        .btn-max { background: transparent; }
        .btn-close { background: transparent; }

        /* --- Main Layout --- */
        .app-container {
            display: flex;
            flex: 1;
            overflow: hidden;
        }

        /* --- Sidebar --- */
        .sidebar {
            width: 260px;
            background-color: var(--sidebar-bg); /* Slightly off-white/grey */
            border-right: 1px solid var(--border-color);
            display: flex;
            flex-direction: column;
            padding: 16px;
            overflow-y: auto;
            flex-shrink: 0;
        }

        .back-link {
            display: flex;
            align-items: center;
            color: var(--text-primary);
            text-decoration: none;
            font-size: 14px;
            margin-bottom: 20px;
            gap: 8px;
        }
        .back-link svg { width: 16px; height: 16px; fill: currentColor; }

        .search-box {
            position: relative;
            margin-bottom: 24px;
        }
        .search-box input {
            width: 100%;
            padding: 8px 12px 8px 32px;
            border: 1px solid var(--border-color);
            border-radius: 6px;
            font-size: 13px;
            outline: none;
            background: white;
        }
        .search-box input::placeholder { color: #9ca3af; }
        .search-icon {
            position: absolute;
            left: 10px;
            top: 50%;
            transform: translateY(-50%);
            width: 14px;
            height: 14px;
            fill: #9ca3af;
        }

        .nav-section {
            margin-bottom: 24px;
        }
        .nav-header {
            font-size: 11px;
            font-weight: 600;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 8px;
            padding-left: 12px;
        }
        .nav-item {
            display: flex;
            align-items: center;
            padding: 8px 12px;
            border-radius: 6px;
            cursor: pointer;
            font-size: 14px;
            color: var(--text-primary);
            text-decoration: none;
            gap: 10px;
            transition: background 0.1s;
        }
        .nav-item:hover {
            background-color: rgba(0,0,0,0.03);
        }
        .nav-item.active {
            background-color: #e5e7eb; /* Light grey active state */
            font-weight: 500;
        }
        .nav-icon {
            width: 16px;
            height: 16px;
            fill: #374151;
            flex-shrink: 0;
        }

        /* --- Main Content --- */
        .main-content {
            flex: 1;
            padding: 32px 48px;
            overflow-y: auto;
            position: relative;
            background-color: #fff;
        }

        h1 {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 24px;
            color: var(--text-primary);
        }

        .settings-group {
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 16px;
            background-color: #fff;
        }

        .group-title {
            font-size: 15px;
            font-weight: 600;
            margin-bottom: 8px;
            color: var(--text-primary);
        }

        .group-text {
            font-size: 13px;
            line-height: 1.5;
            color: var(--text-secondary);
        }

        .group-text code {
            background-color: #f3f4f6;
            padding: 2px 4px;
            border-radius: 4px;
            font-family: monospace;
            font-size: 12px;
            color: #111;
        }

        /* Toggle Buttons */
        .toggle-group {
            display: flex;
            gap: 8px;
            margin-top: 8px;
        }
        .toggle-btn {
            padding: 4px 12px;
            font-size: 13px;
            border-radius: 6px;
            border: 1px solid var(--border-color);
            background: #fff;
            color: var(--text-secondary);
            cursor: pointer;
        }
        .toggle-btn.active {
            background: #f3f4f6;
            color: var(--text-primary);
            font-weight: 500;
            border-color: #d1d5db;
        }

        /* Toast / Banner */
        .toast-banner {
            position: fixed;
            bottom: 30px;
            right: 30px; /* Adjusted to match screenshot placement roughly or center bottom? 
                           Screenshot shows it at the very bottom of the content area or overlaying. 
                           Let's put it fixed at bottom of viewport to be safe, or absolute bottom of container. 
                           The screenshot has it inside the scroll area at the bottom. */
            position: absolute;
            bottom: 20px;
            left: 48px;
            right: 48px;
            background: #fff;
            border: 1px solid var(--border-color);
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            padding: 12px 16px;
            border-radius: 8px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 13px;
            color: var(--text-primary);
            z-index: 10;
        }
        .dismiss-btn {
            background: none;
            border: none;
            color: var(--text-primary);
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            padding: 4px 8px;
            border-radius: 4px;
        }
        .dismiss-btn:hover {
            background-color: #f3f4f6;
        }

    </style>
</head>
